    ["<Assistant_Title1>е€ќзЋ°ж ји°ѓ</>\n<Assistant_Title2>ж€ђе°±е€†з±»пјљ</>дј‘й—І-еџЋе Ў\n<Assistant_Title2>и§Јй”ЃжќЎд»¶пјљ</>зґЇи®ЎиЋ·еѕ—100дёЄе®¶е…·"] = "<Assistant_Title1>РџРµСЂРІС‹Р№ РїСЂРёР·РЅР°Рє РІРєСѓСЃР°</>\n<Assistant_Title2>РљР°С‚РµРіРѕСЂРёСЏ РґРѕСЃС‚РёР¶РµРЅРёСЏ: </>РћС‚РґС‹С… вЂ” Р—Р°РјРѕРє\n<Assistant_Title2>РЈСЃР»РѕРІРёРµ СЂР°Р·Р±Р»РѕРєРёСЂРѕРІРєРё: </>РЎРѕР±СЂР°С‚СЊ СЃСѓРјРјР°СЂРЅРѕ 100 РїСЂРµРґРјРµС‚РѕРІ РјРµР±РµР»Рё",
